package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.CalculationStatus;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import org.hibernate.annotations.Immutable;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Immutable @Table(name="program_calculation",uniqueConstraints=@UniqueConstraint(name="uq_program_calculation_revision",columnNames={"tenant_id","participant_id","revision"}),indexes=@Index(name="ix_program_calculation_tenant_program",columnList="tenant_id, program_id, status"))
public class ProgramCalculation extends TenantAwareAuditEntity{
 @Id@Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="program_id",columnDefinition="uuid",nullable=false,updatable=false)private UUID programId;@Column(name="participant_id",columnDefinition="uuid",nullable=false,updatable=false)private UUID participantId;@Column(nullable=false,updatable=false)private int revision;@JdbcTypeCode(SqlTypes.JSON)@Column(name="contributions_json",columnDefinition="jsonb",nullable=false,updatable=false)private String contributionsJson;@Column(name="raw_score",precision=9,scale=4,nullable=false,updatable=false)private BigDecimal rawScore;@Column(name="normalized_score",precision=9,scale=4,nullable=false,updatable=false)private BigDecimal normalizedScore;@Column(name="adjusted_score",precision=9,scale=4,nullable=false,updatable=false)private BigDecimal adjustedScore;@Column(name="calculated_grade",length=20,nullable=false,updatable=false)private String calculatedGrade;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20,updatable=false)private CalculationStatus status;@Column(nullable=false,length=1000,updatable=false)private String formula;@JdbcTypeCode(SqlTypes.JSON)@Column(name="warnings_json",columnDefinition="jsonb",nullable=false,updatable=false)private String warningsJson;@Column(name="calculated_at",nullable=false,updatable=false)private Instant calculatedAt;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();if(calculatedAt==null)calculatedAt=Instant.now();}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getProgramId(){return programId;}public void setProgramId(UUID v){programId=v;}public UUID getParticipantId(){return participantId;}public void setParticipantId(UUID v){participantId=v;}public int getRevision(){return revision;}public void setRevision(int v){revision=v;}public String getContributionsJson(){return contributionsJson;}public void setContributionsJson(String v){contributionsJson=v;}public BigDecimal getRawScore(){return rawScore;}public void setRawScore(BigDecimal v){rawScore=v;}public BigDecimal getNormalizedScore(){return normalizedScore;}public void setNormalizedScore(BigDecimal v){normalizedScore=v;}public BigDecimal getAdjustedScore(){return adjustedScore;}public void setAdjustedScore(BigDecimal v){adjustedScore=v;}public String getCalculatedGrade(){return calculatedGrade;}public void setCalculatedGrade(String v){calculatedGrade=v;}public CalculationStatus getStatus(){return status;}public void setStatus(CalculationStatus v){status=v;}public String getFormula(){return formula;}public void setFormula(String v){formula=v;}public String getWarningsJson(){return warningsJson;}public void setWarningsJson(String v){warningsJson=v;}public Instant getCalculatedAt(){return calculatedAt;}public void setCalculatedAt(Instant v){calculatedAt=v;}
}
